// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { ArrayLike } from '@stdlib/types/array';
import { ComplexLike } from '@stdlib/types/complex';
import { ndarray, complexndarray, realndarray, genericndarray } from '@stdlib/types/ndarray';

/**
* Input array.
*/
type InputArray = complexndarray | realndarray | genericndarray<number>;

/**
* Alpha parameter.
*/
type Alpha = ndarray | number | ComplexLike;

/**
* Beta parameter.
*/
type Beta = ndarray | number | ComplexLike;

/**
* Interface defining options.
*/
interface Options {
	/**
	* List of dimensions over which to perform operation.
	*/
	dims?: ArrayLike<number>;
}

/**
* Interface for performing an operation on an ndarray.
*/
interface Axpb {
	/**
	* Multiplies each element in an input ndarray by a scalar constant and adds a scalar constant to each result along one or more ndarray dimensions.
	*
	* ## Notes
	*
	* -   The input ndarray is modified **in-place** (i.e., the input ndarray is **mutated**).
	* -   By default, the function multiplies each element by `1.0` and adds `0.0` (i.e., performs a no-op).
	*
	* @param x - input ndarray
	* @param options - function options
	* @returns output ndarray
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	*
	* var x = array( [ -2.0, 1.0, 3.0, -5.0 ] );
	*
	* var y = axpb( x );
	* // returns <ndarray>[ -2.0, 1.0, 3.0, -5.0 ]
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	*
	* var x = array( [ [ -2.0, 1.0 ], [ 3.0, -5.0 ] ] );
	*
	* var y = axpb( x, { 'dims': [ 0 ] } );
	* // returns <ndarray>
	*/
	<T extends InputArray = InputArray>( x: T, options?: Options ): T;

	/**
	* Multiplies each element in an input ndarray by a scalar constant and adds a scalar constant to each result along one or more ndarray dimensions.
	*
	* ## Notes
	*
	* -   The input ndarray is modified **in-place** (i.e., the input ndarray is **mutated**).
	*
	* @param x - input ndarray
	* @param alpha - scalar constant to multiply
	* @param options - function options
	* @returns output ndarray
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	*
	* var x = array( [ -2.0, 1.0, 3.0, -5.0 ] );
	*
	* var y = axpb( x, 5.0 );
	* // returns <ndarray>[ -10.0, 5.0, 15.0, -25.0 ]
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	*
	* var x = array( [ [ -2.0, 1.0 ], [ 3.0, -5.0 ] ] );
	*
	* var y = axpb( x, 5.0, { 'dims': [ 0 ] } );
	* // returns <ndarray>[ [ -10.0, 5.0 ], [ 15.0, -25.0 ] ]
	*/
	<T extends InputArray = InputArray>( x: T, alpha: Alpha, options?: Options ): T;

	/**
	* Multiplies each element in an input ndarray by a scalar constant and adds a scalar constant to each result along one or more ndarray dimensions.
	*
	* ## Notes
	*
	* -   The input ndarray is modified **in-place** (i.e., the input ndarray is **mutated**).
	*
	* @param x - input ndarray
	* @param alpha - scalar constant to multiply
	* @param beta - scalar constant to add
	* @param options - function options
	* @returns output ndarray
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	*
	* var x = array( [ -2.0, 1.0, 3.0, -5.0 ] );
	*
	* var y = axpb( x, 5.0, 3.0 );
	* // returns <ndarray>[ -7.0, 8.0, 18.0, -22.0 ]
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	*
	* var x = array( [ [ -2.0, 1.0 ], [ 3.0, -5.0 ] ] );
	*
	* var y = axpb( x, 5.0, 3.0, { 'dims': [ 0 ] } );
	* // returns <ndarray>[ [ -7.0, 8.0 ], [ 18.0, -22.0 ] ]
	*/
	<T extends InputArray = InputArray>( x: T, alpha: Alpha, beta: Beta, options?: Options ): T;
}

/**
* Multiplies each element in an input ndarray by a scalar constant and adds a scalar constant to each result along one or more ndarray dimensions.
*
* ## Notes
*
* -   The input ndarray is modified **in-place** (i.e., the input ndarray is **mutated**).
* -   By default, the function multiplies each element by `1.0` and adds `0.0` (i.e., performs a no-op).
*
* @param x - input ndarray
* @param alpha - scalar constant to multiply
* @param beta - scalar constant to add
* @param options - function options
* @returns output ndarray
*
* @example
* var array = require( '@stdlib/ndarray/array' );
*
* var x = array( [ -2.0, 1.0, 3.0, -5.0 ] );
*
* var y = axpb( x, 5.0, 3.0 );
* // returns <ndarray>[ -7.0, 8.0, 18.0, -22.0 ]
*
* @example
* var array = require( '@stdlib/ndarray/array' );
*
* var x = array( [ -2.0, 1.0, 3.0, -5.0 ] );
*
* var y = axpb( x, 5.0 );
* // returns <ndarray>[ -10.0, 5.0, 15.0, -25.0 ]
*
* @example
* var array = require( '@stdlib/ndarray/array' );
*
* var x = array( [ -2.0, 1.0, 3.0, -5.0 ] );
*
* var y = axpb( x );
* // returns <ndarray>[ -2.0, 1.0, 3.0, -5.0 ]
*/
declare const axpb: Axpb;


// EXPORTS //

export = axpb;
